import os
import mimetypes
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Optional

import boto3


REQUIRED_FIELDS = {
    "vendor_name": {"aliases": ["VENDOR_NAME"]},
    "invoice_id": {"aliases": ["INVOICE_RECEIPT_ID", "INVOICE_RECEIPT_NUMBER"]},
    "invoice_date": {"aliases": ["INVOICE_RECEIPT_DATE"]},
    "total": {"aliases": ["TOTAL"]},
}


def _to_decimal(value: Any) -> Optional[Decimal]:
    if value is None:
        return None
    try:
        return Decimal(str(value).replace(",", "").strip())
    except (InvalidOperation, AttributeError):
        return None


def _normalize_text(value: Optional[str]) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _read_file_bytes(path: str) -> bytes:
    with open(path, "rb") as f:
        return f.read()


def _guess_mime_type(path: str) -> str:
    mime, _ = mimetypes.guess_type(path)
    return mime or "application/octet-stream"


def _extract_summary_fields(expense_document: Dict[str, Any]) -> Dict[str, List[Dict[str, Any]]]:
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for field in expense_document.get("SummaryFields", []):
        field_type = (((field.get("Type") or {}).get("Text")) or "").strip().upper()
        if not field_type:
            continue
        grouped.setdefault(field_type, []).append(field)
    return grouped


def _best_field_candidate(fields: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    if not fields:
        return None

    def score(field: Dict[str, Any]) -> float:
        type_conf = float(((field.get("Type") or {}).get("Confidence")) or 0.0)
        value_conf = float(((field.get("ValueDetection") or {}).get("Confidence")) or 0.0)
        return max(type_conf, value_conf)

    return max(fields, key=score)


def _field_value(field: Optional[Dict[str, Any]]) -> Optional[str]:
    if not field:
        return None
    return _normalize_text(((field.get("ValueDetection") or {}).get("Text")))


def _field_confidence(field: Optional[Dict[str, Any]]) -> Optional[float]:
    if not field:
        return None
    value_conf = ((field.get("ValueDetection") or {}).get("Confidence"))
    type_conf = ((field.get("Type") or {}).get("Confidence"))
    if value_conf is not None:
        return float(value_conf)
    if type_conf is not None:
        return float(type_conf)
    return None


def _find_required_field(summary_fields: Dict[str, List[Dict[str, Any]]], aliases: List[str]) -> Optional[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = []
    for alias in aliases:
        candidates.extend(summary_fields.get(alias.upper(), []))
    return _best_field_candidate(candidates)


def validate_invoice_fields(
    file_path: str,
    min_confidence: float = 80.0,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")

    document_bytes = _read_file_bytes(file_path)
    response = client.analyze_expense(
        Document={
            "Bytes": document_bytes
        }
    )

    expense_documents = response.get("ExpenseDocuments", [])
    if not expense_documents:
        return {
            "provider": "aws_textract",
            "operation": "AnalyzeExpense",
            "file_path": file_path,
            "mime_type": _guess_mime_type(file_path),
            "valid": False,
            "min_confidence": min_confidence,
            "errors": ["No expense documents detected."],
            "fields": {},
        }

    expense_document = expense_documents[0]
    summary_fields = _extract_summary_fields(expense_document)

    result_fields: Dict[str, Dict[str, Any]] = {}
    errors: List[str] = []

    for output_name, config in REQUIRED_FIELDS.items():
        field = _find_required_field(summary_fields, config["aliases"])
        value = _field_value(field)
        confidence = _field_confidence(field)

        field_result = {
            "required": True,
            "present": value is not None,
            "value": value,
            "confidence": confidence,
            "meets_confidence_threshold": confidence is not None and confidence >= min_confidence,
            "source_type": (((field or {}).get("Type") or {}).get("Text")) if field else None,
        }

        if output_name == "total":
            numeric_value = _to_decimal(value)
            field_result["numeric_value"] = str(numeric_value) if numeric_value is not None else None
            if value is not None and numeric_value is None:
                errors.append("Field 'total' is present but not a valid numeric amount.")
            if numeric_value is not None and numeric_value < 0:
                errors.append("Field 'total' must be non-negative.")

        result_fields[output_name] = field_result

        if not field_result["present"]:
            errors.append(f"Missing required field: {output_name}")
        elif not field_result["meets_confidence_threshold"]:
            errors.append(
                f"Field '{output_name}' confidence below threshold: "
                f"{confidence if confidence is not None else 'None'} < {min_confidence}"
            )

    return {
        "provider": "aws_textract",
        "operation": "AnalyzeExpense",
        "file_path": file_path,
        "mime_type": _guess_mime_type(file_path),
        "valid": len(errors) == 0,
        "min_confidence": min_confidence,
        "document_metadata": {
            "expense_index": expense_document.get("ExpenseIndex"),
        },
        "fields": result_fields,
        "errors": errors,
        "raw_response": response,
    }
